// Some portions generated by Codex
package org.eclipse.rdf4j.http.client;

import static org.junit.jupiter.api.Assertions.*;

import java.lang.classfile.ClassFile;
import java.lang.classfile.instruction.InvokeInstruction;
import java.lang.ref.WeakReference;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

import org.eclipse.rdf4j.model.Value;
import org.junit.jupiter.api.Test;

class ExternalValueInitializerRestorationTest {
	@Test
	void emptyRestorationUsesSetWithoutRemovingSlot() throws Exception {
		try (var bytes = QueryExecutionContext.class.getResourceAsStream("QueryExecutionContext.class")) {
			var model = ClassFile.of().parse(bytes.readAllBytes());
			var method = model.methods()
					.stream()
					.filter(m -> m.methodName().equalsString("setExternalValueInitializer"))
					.findFirst()
					.orElseThrow();
			var calls = method.code()
					.orElseThrow()
					.elementList()
					.stream()
					.filter(InvokeInstruction.class::isInstance)
					.map(InvokeInstruction.class::cast)
					.filter(i -> i.owner().asInternalName().equals("java/lang/ThreadLocal"))
					.map(i -> i.name().stringValue())
					.toList();
			assertEquals(java.util.List.of("set"), calls,
					"Restoration must update the existing slot, not remove and reinitialize it");
		}
	}

	@Test
	void sameConsumerStillHasSeparateIdempotentTokens() {
		Consumer<Value> same = value -> {
		};
		assertNull(QueryExecutionContext.getExternalValueInitializer());
		var outer = QueryExecutionContext.activateExternalValueInitializer(same);
		try {
			var inner = QueryExecutionContext.activateExternalValueInitializer(same);
			inner.close();
			assertSame(same, QueryExecutionContext.getExternalValueInitializer());
			inner.close();
			assertSame(same, QueryExecutionContext.getExternalValueInitializer());
		} finally {
			outer.close();
		}
		outer.close();
		assertNull(QueryExecutionContext.getExternalValueInitializer());
		assertNull(QueryExecutionContext.captureReplayContext());
	}

	@Test
	void wrongOrderKeepsExistingIdentityGuardBehavior() throws Exception {
		// Wrong-order close currently consumes the token without unwinding a different consumer.
		// Use a disposable worker: this intentionally tests baseline misuse, not a safe cleanup contract.
		try (var worker = Executors.newSingleThreadExecutor()) {
			worker.submit(() -> {
				Consumer<Value> first = value -> {
				};
				Consumer<Value> second = value -> {
				};
				var outer = QueryExecutionContext.activateExternalValueInitializer(first);
				var inner = QueryExecutionContext.activateExternalValueInitializer(second);
				outer.close();
				assertSame(second, QueryExecutionContext.getExternalValueInitializer());
				inner.close();
				assertSame(first, QueryExecutionContext.getExternalValueInitializer());
				outer.close();
				assertSame(first, QueryExecutionContext.getExternalValueInitializer());
			}).get(5, TimeUnit.SECONDS);
		}
	}

	@Test
	void workerActivationFailureRestoresPreviousInitializer() throws Exception {
		Consumer<Value> captured = value -> {
		};
		Consumer<Value> previous = value -> {
		};
		IllegalStateException failure = new IllegalStateException("activation failed");
		try (var worker = Executors.newSingleThreadExecutor();
				var initializer = QueryExecutionContext.activateExternalValueInitializer(captured);
				var scope = QueryExecutionContext.activateReplaySafepoint(() -> {
				}, () -> () -> {
					throw failure;
				})) {
			var context = QueryExecutionContext.captureReplayContext();
			worker.submit(() -> {
				try (var prior = QueryExecutionContext.activateExternalValueInitializer(previous)) {
					assertSame(failure, assertThrows(IllegalStateException.class, context::activate));
					assertSame(previous, QueryExecutionContext.getExternalValueInitializer());
				}
				assertNull(QueryExecutionContext.getExternalValueInitializer());
				assertNull(QueryExecutionContext.captureReplayContext());
			}).get(5, TimeUnit.SECONDS);
		}
		assertNull(QueryExecutionContext.getExternalValueInitializer());
		assertNull(QueryExecutionContext.captureReplayContext());
	}

	@Test
	void closedScopesAndReleasedReplayContextDoNotRetainOwner() throws Exception {
		try (var worker = Executors.newSingleThreadExecutor()) {
			var reference = worker.submit(() -> installAndReleaseOwner()).get(5, TimeUnit.SECONDS);
			// Keep the worker alive while checking collection: thread death must not hide a retained TL owner.
			for (int attempt = 0; reference.get() != null && attempt < 100; attempt++) {
				System.gc();
				Thread.sleep(10);
			}
			assertNull(reference.get(), "A completed initializer/replay scope must not retain its Consumer");
			worker.submit(() -> {
				assertNull(QueryExecutionContext.getExternalValueInitializer());
				assertNull(QueryExecutionContext.captureReplayContext());
			}).get(5, TimeUnit.SECONDS);
		}
	}

	private static WeakReference<Consumer<Value>> installAndReleaseOwner() {
		Consumer<Value> owner = new Consumer<>() {
			@Override
			public void accept(Value ignored) {
			}
		};
		var weak = new WeakReference<>(owner);
		QueryExecutionContext.ReplayContext context;
		try (var activation = QueryExecutionContext.activateExternalValueInitializer(owner)) {
			context = QueryExecutionContext.captureReplayContext();
		}
		try (var activation = context.activate()) {
			assertSame(owner, QueryExecutionContext.getExternalValueInitializer());
		}
		assertNull(QueryExecutionContext.getExternalValueInitializer());
		return weak;
	}
}
